import mongoose from "mongoose";

const ruleSchema =
new mongoose.Schema({

    action: String,

    source: String,

    destination: String,

    port: Number,

    protocol: String,

    direction: String,

    zone: String,

    riskScore: Number,

    // LOW | MEDIUM | HIGH | CRITICAL, from riskEngine.js's
    // assessRisk(). Lets the Firewall Rules page show a
    // severity badge without recomputing it client-side.
    riskLevel: String,

    // The real iptables command generated by
    // firewallService.js's deployRule() for this rule —
    // e.g. "iptables -A INPUT -s 10.0.2.0/24 -p tcp
    // --dport 443 -j ACCEPT"
    iptablesRule: String,

    firewallStatus: String,

    enabled: {
        type: Boolean,
        default: true
    }

}, {
    timestamps: true
});

export default mongoose.model(
    "Rule",
    ruleSchema
);